#include <stdio.h>

typedef int Rule(int);

static int keep(int x) { return x; }
static int clamp(int x) { return x > 10 ? 10 : x; }

static Rule *pick(int strict) {
    return strict ? clamp : keep;
}

int main(void) {
    printf("%d %d\n", pick(0)(25), pick(1)(25));
    return 0;
}
